import sys

def solve():
	(n,) = rv()
	edges = [list() for _ in range(n)]
	for i in range(n - 1):
		(x, y, w) = rv()
		edges[x - 1].append((y - 1, w))
		edges[y - 1].append((x - 1, w))
	res = dfs(0, -1, edges)
	print(res[0] * 2 - res[1])

def dfs(cur, prev, edges):
	(total, single) = (0, 0)
	for (nxt, weight) in edges[cur]:
		if nxt != prev:
			temp = dfs(nxt, cur, edges)
			total += temp[0] + weight
			single = max(single, temp[1] + weight)
	return (total, single)

def prt(l):
	return print(' '.join(l))

def rv():
	return map(int, input().split())

def rl(n):
	return [list(map(int, input().split())) for _ in range(n)]
